enum {
    SURFER_LAST = 18,
    LEVEL_LAST = 32,
    GOAL_COMPETITION_1 = 3,
    GOAL_COMPETITION_2 = 4,
    GOAL_COMPETITION_3 = 5
};

class stringx {
    char *chars;
    void *my_buf;
public:
    stringx();
    ~stringx();
};

struct CareerData {
    int beach;
    int goal_param[5];
    int reward_param[5];
    char beach_file[32];
    char name[32];
    int goal[5];
    int goal_param_2[5];
    int reward[5];
    int prev_levels[4];
    int next_levels[2];
    float level_duration;
    char stash_name[15];
    int use_ai_surfer;
    char challenge_name[32];
};

extern CareerData CareerDataArray[];

class game {
public:
    int get_level_id();
    int GetSurferIdx(int player);
};

extern game *g_game_ptr;

class Career {
public:
    class Level {
        int my_id;
        bool is_new;
        bool advanced;
        bool unlocked;
        bool goals[5];
    public:
        void SetGoalDone(const int goalIdx);
        bool IsGoalDone(const int goalIdx) const;
    };
private:
    char prefix[0x1019c];
public:
    Level levels[LEVEL_LAST];
    void OnGoalReDone(const int levelIdx, const int goalIdx);
    void OnGoalDone(const int levelIdx, const int goalIdx);
    static bool GetGoalText(int level_num, int goal_num, stringx &goal_text);
};

extern Career *g_career;

class JudgingSystem {
public:
    struct RUN {
        float regionScores[3];
    };
    struct RESULT {
        RUN runs[3];
        int rank;
    };
protected:
    float skills[SURFER_LAST];
    bool isCompetitor[SURFER_LAST];
    float difficulties[3];
    RESULT results[SURFER_LAST];
    int currRunIdx;
    bool over;
    int numPlayerWipeouts;
    void AdvanceRun(void);
};

void JudgingSystem::AdvanceRun(void)
{
	int	levelIdx = g_game_ptr->get_level_id();
	int	requiredRank;

	numPlayerWipeouts = 0;
	currRunIdx++;

	if (currRunIdx == 3)
	{
		currRunIdx = 0;
		over = true;

		if (CareerDataArray[levelIdx].goal[0] == GOAL_COMPETITION_3)
			requiredRank = 3;
		else if (CareerDataArray[levelIdx].goal[0] == GOAL_COMPETITION_2)
			requiredRank = 2;
		else
			requiredRank = 1;

		if (results[g_game_ptr->GetSurferIdx(0)].rank <= requiredRank)
		{
			if (!g_career->levels[levelIdx].IsGoalDone(0))
			{
				stringx completion_message;
				g_career->GetGoalText(levelIdx, 0, completion_message);
				g_career->levels[levelIdx].SetGoalDone(0);
				g_career->OnGoalDone(levelIdx, 0);
			}
			else
				g_career->OnGoalReDone(levelIdx, 0);
		}
	}
}
